Pqrs.Valid If:
=IF(
  IN(
    LOOKUP(USEREMAIL(), "Gestores", "CorreoGestor", "Rol"),
    {"Administrador","Creador"}
  ),
  ORDERBY(
    SELECT(
      Departamentos[ID_Departamento],
      [Estado] = "Activo"
    ),
    [Departamento]
  ),
  ORDERBY(
    SELECT(
      Departamentos[ID_Departamento],
      AND(
        [CorreoDpto] = USEREMAIL(),
        [Estado] = "Activo"
      )
    ),
    [Departamento]
  )
)

GestionPqr.Valid If:
=SELECT(
  Pqrs[ID_PQR],
  AND(
    [Estado_Pqr] <> "Cerrada",
    OR(
      IN(
        LOOKUP(USEREMAIL(), "Gestores", "CorreoGestor", "Rol"),
        {"Administrador","Creador"}
      ),
      [Departamento] = LOOKUP(USEREMAIL(), "Departamentos", "CorreoDpto", "ID_Departamento")
    )
  )
)

Gestores.Security filter:
=AND(
  OR(
    IN(
      USEREMAIL(),
      {
        "[REDACTED_EMAIL]",
        "[REDACTED_EMAIL]"
      }
    ),
    [ID_Departamento] =
    LOOKUP(
      USEREMAIL(),
      "Departamentos",
      "CorreoDpto",
      "ID_Departamento"
    )
  ),
  NOT(
    AND(
      USEREMAIL() = "[REDACTED_EMAIL]",
      [CorreoGestor] = "[REDACTED_EMAIL]"
    )
  )
)

Departamentos.Security filter:
=AND(
  OR(
    USEREMAIL() = "[REDACTED_EMAIL]",
    USEREMAIL() = "[REDACTED_EMAIL]",
    [CorreoDpto] = USEREMAIL()
  ),
  NOT(
    AND(
      USEREMAIL() = "[REDACTED_EMAIL]",
      [CorreoDpto] = "[REDACTED_EMAIL]"
    )
  )
)

